    VALUES (v_bag, v_section, $q$Foresight Premier$q$, $q$Foresight Sports$q$, NULL, NULL, $q$Pricing: free; runs on Windows 10/11 64-bit
Discussed in 3 independent sources$q$, NULL, $q$software$q$, $j${"minimum":"{\"gpu\":\"RTX 3060 Ti, RTX 4060 Ti, or RX 6600 XT (8GB) for 1080p Low\",\"cpu\":\"Core i5-12500 or Ryzen 5 5600\",\"ram_gb\":16,\"storage_gb\":20}","recommended":"{\"gpu\":\"RTX 4070, RTX 3080 12GB, or RX 7800 XT (12GB) for 1080p maxed or 4K Medium\",\"cpu\":\"i7-12700K or Ryzen 7 7700X\",\"ram_gb\":32}","ultra":"{\"gpu\":\"RTX 4080 or RX 7900 XTX (16GB) for 4K High\",\"ram_gb\":32}","source_urls":"[\"https://premier.foresightsports.com/\"]","notes":"Premier now lists AMD GPUs, which FSX Play never did. The Foresight help article (RTX 4060 8GB + i5-12500 + 16GB for Medium/High) could not be fetched (403) and conflicts slightly with the Premier page.","pricing_note":"Course Pass $295/yr (35 courses) or Course Pass Pro $595/yr (111 courses), both need a Foresight+ Silver or Gold membership","price_source_url":"https://premier.foresightsports.com/","os":"Windows 10/11 64-bit","pricing_model":"free","platform":"Windows 10/11 64-bit"}$j$::jsonb, NULL, 1, 22)
    RETURNING id INTO v_item;
  ELSE
    UPDATE bag_items SET
      section_id = v_section,
      brand = $q$Foresight Sports$q$,
      custom_description = NULL,
      why_chosen = NULL,
      notes = $q$Pricing: free; runs on Windows 10/11 64-bit
Discussed in 3 independent sources$q$,
      price_paid = NULL,
      item_type = $q$software$q$,
      specs = $j${"minimum":"{\"gpu\":\"RTX 3060 Ti, RTX 4060 Ti, or RX 6600 XT (8GB) for 1080p Low\",\"cpu\":\"Core i5-12500 or Ryzen 5 5600\",\"ram_gb\":16,\"storage_gb\":20}","recommended":"{\"gpu\":\"RTX 4070, RTX 3080 12GB, or RX 7800 XT (12GB) for 1080p maxed or 4K Medium\",\"cpu\":\"i7-12700K or Ryzen 7 7700X\",\"ram_gb\":32}","ultra":"{\"gpu\":\"RTX 4080 or RX 7900 XTX (16GB) for 4K High\",\"ram_gb\":32}","source_urls":"[\"https://premier.foresightsports.com/\"]","notes":"Premier now lists AMD GPUs, which FSX Play never did. The Foresight help article (RTX 4060 8GB + i5-12500 + 16GB for Medium/High) could not be fetched (403) and conflicts slightly with the Premier page.","pricing_note":"Course Pass $295/yr (35 courses) or Course Pass Pro $595/yr (111 courses), both need a Foresight+ Silver or Gold membership","price_source_url":"https://premier.foresightsports.com/","os":"Windows 10/11 64-bit","pricing_model":"free","platform":"Windows 10/11 64-bit"}$j$::jsonb,
      photo_url = NULL,
      quantity = 1,
      sort_index = 22
    WHERE id = v_item;
  END IF;
  IF v_first_item IS NULL THEN v_first_item := v_item; END IF;
  DELETE FROM links WHERE bag_item_id = v_item;

  -- item 23: Creative Golf 3D
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$Software$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$Creative Golf 3D$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$Creative Golf 3D$q$, $q$Datacrea (sold via Carl's Place, Foresight, FlightScope)$q$, NULL, NULL, $q$Pricing: free; runs on Windows 7 to 11 64-bit
Discussed in 1 independent sources$q$, NULL, $q$software$q$, $j${"minimum":"{\"gpu\":\"Dedicated GPU with 1GB VRAM (older versions); 4GB VRAM for the 2025 Advanced build\",\"cpu\":\"2.5 GHz / Intel i3 or better\",\"ram_gb\":2,\"storage_gb\":42}","recommended":"{\"gpu\":\"GTX 1070 class (Foresight listing); 8GB VRAM NVIDIA for the 2025 build\",\"cpu\":\"Intel i5\",\"ram_gb\":8,\"note\":\"2025 review lists 16GB minimum, 32GB optimum\"}","source_urls":"[\"https://shop.carlofet.com/creative-golf-3d-software\",\"https://www.foresightsports.com/products/creative-golf\",\"https://mygolfsimulator.com/golf-simulator-system-requirements/\"]","notes":"No single current official spec page found; figures differ between the 2021 manual, retailer tables, and the 2025 review.","os":"Windows 7 to 11 64-bit","pricing_model":"free","platform":"Windows 7 to 11 64-bit"}$j$::jsonb, NULL, 1, 23)
    RETURNING id INTO v_item;
  ELSE
    UPDATE bag_items SET
      section_id = v_section,
      brand = $q$Datacrea (sold via Carl's Place, Foresight, FlightScope)$q$,
      custom_description = NULL,
      why_chosen = NULL,
      notes = $q$Pricing: free; runs on Windows 7 to 11 64-bit
Discussed in 1 independent sources$q$,
      price_paid = NULL,
      item_type = $q$software$q$,
      specs = $j${"minimum":"{\"gpu\":\"Dedicated GPU with 1GB VRAM (older versions); 4GB VRAM for the 2025 Advanced build\",\"cpu\":\"2.5 GHz / Intel i3 or better\",\"ram_gb\":2,\"storage_gb\":42}","recommended":"{\"gpu\":\"GTX 1070 class (Foresight listing); 8GB VRAM NVIDIA for the 2025 build\",\"cpu\":\"Intel i5\",\"ram_gb\":8,\"note\":\"2025 review lists 16GB minimum, 32GB optimum\"}","source_urls":"[\"https://shop.carlofet.com/creative-golf-3d-software\",\"https://www.foresightsports.com/products/creative-golf\",\"https://mygolfsimulator.com/golf-simulator-system-requirements/\"]","notes":"No single current official spec page found; figures differ between the 2021 manual, retailer tables, and the 2025 review.","os":"Windows 7 to 11 64-bit","pricing_model":"free","platform":"Windows 7 to 11 64-bit"}$j$::jsonb,
      photo_url = NULL,
      quantity = 1,
      sort_index = 23
    WHERE id = v_item;
  END IF;
  IF v_first_item IS NULL THEN v_first_item := v_item; END IF;
  DELETE FROM links WHERE bag_item_id = v_item;
  INSERT INTO links (bag_item_id, kind, url, label) VALUES
    (v_item, $q$product$q$, $q$https://creativegolf.com/$q$, $q$Maker's page$q$);

  -- Items in the bag that are not in the JSON are reported, never deleted (no --prune here).
  SELECT count(*) INTO v_stale FROM bag_items
  WHERE bag_id = v_bag AND custom_name NOT IN ($q$Legion 5i / Legion Pro 5i / Legion Pro 7i gaming laptops (and LOQ 15 budget sibling)$q$, $q$TUF Gaming A15 / F15 / TUF 16 and ROG Strix G16 / G18 gaming laptops$q$, $q$Thin 15 / Katana 15 gaming laptops$q$, $q$G15 / G16 gaming laptops (now succeeded by Alienware 15 / 16 Aurora)$q$, $q$Nitro V 15 / Nitro V 16 / Nitro 16 (and Predator Helios / Triton) gaming laptops$q$, $q$SG3 series simulator desktops (SG3-5602, SG3-5702, SG3-5702Ti, SG3-5802) and M3H laptop$q$, $q$Costco and Amazon RTX 4060 to 5070 class towers (iBUYPOWER Slate Mesh and Element, CyberPowerPC Gamer Xtreme, Skytech Azure 3 and Blaze 3)$q$, $q$OMEN 35L desktop and OMEN / Victus gaming laptops$q$, $q$Refurbished office tower plus a used GPU (Dell OptiPlex class, or a used gaming PC)$q$, $q$Aurora desktop and Alienware 15 / 16 / m15 / m18 laptops$q$, $q$Approach R10 run from a phone or iPad (Garmin Golf app, Home Tee Hero, E6 Connect iOS, Awesome Golf)$q$, $q$MLM2PRO run from a phone or iPad (Rapsodo app, Awesome Golf, E6 Apex/Connect); GSPro needs a PC$q$, $q$Mevo+ run from an iPad (FS Golf, E6 Connect iOS 12-course license, Awesome Golf)$q$, $q$iPad plus Apple TV 4K (AirPlay) or a Lightning / USB-C to HDMI adapter as the no-PC display bridge$q$, $q$GSPro$q$, $q$The Golf Club 2019 (TGC 2019)$q$, $q$E6 Connect$q$, $q$E6 (2026)$q$, $q$Simulator$q$, $q$FSX Play$q$, $q$software (Refine / Refine+ / View, third-party at 4K)$q$, $q$Foresight Premier$q$, $q$Creative Golf 3D$q$);
  IF v_stale > 0 THEN
    RAISE NOTICE 'sim-computers: % item(s) in the bag are not in the JSON', v_stale;
  END IF;

  -- hero_item_id: the first item, only when the bag has none.
  IF v_first_item IS NOT NULL THEN
    UPDATE bags SET hero_item_id = v_first_item WHERE id = v_bag AND hero_item_id IS NULL;
  END IF;
  RAISE NOTICE 'sim-computers: bag %, 4 section(s), 23 item(s) upserted', v_bag;
END
$seed$;

-- 6. Summary: one row per bag.
SELECT
  b.code,
  (SELECT count(*) FROM bag_sections s WHERE s.bag_id = b.id) AS sections,
  (SELECT count(*) FROM bag_items i WHERE i.bag_id = b.id) AS items,
  (SELECT count(*) FROM links l JOIN bag_items i ON i.id = l.bag_item_id WHERE i.bag_id = b.id) AS links
FROM bags b
WHERE b.owner_id = '2c3e503a-78ce-4a8d-ae37-60b4a16d916e'::uuid AND b.code IN ($q$sim-computers$q$)
ORDER BY b.code;

COMMIT;
